<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<title>Conway's Game of Life</title>
<style>
    body {
        background-color: #121212;
        color: #e0e0e0;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 100vh;
        margin: 0;
        padding: 20px;
    }

    h1 { font-weight: 700; color: #fff; text-shadow: 0 0 10px rgba(59, 130, 246, 0.5); margin-bottom: 10px;}

    .controls {
        display: flex; gap: 12px; margin-bottom: 25px; 
        flex-wrap: wrap; justify-content: center;
    }

    button {
        padding: 10px 22px; border: none; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.2s ease; background-color: #333; color: white; box-shadow: 0 4px 6px rgba(0,0,0,0.3); text-transform: uppercase; letter-spacing: 1px;
    }

    button:hover { transform: translateY(-2px); background-color: #555; box-shadow: 0 6px 8px rgba(0,0,0,0.4);}
    button:active { transform: translateY(1px); box-shadow: inset 0 2px 4px rgba(0,0,0,0.5);}

    #life {
        background-color: #1a1a1a; border-radius: 8px; 
        box-shadow: 0 10px 30px rgba(0,0,0,0.6); image-rendering: pixelated;
        width: 600px !important; height: 600px !important; cursor: crosshair; display: block; margin-top: 20px; border: 4px solid #2a2a2a;
    }
</style>
</head>
<body>

<h1 style="margin-bottom:-5px">Conway's Game of Life</h1>

<div class="controls" id="controls">
  <button id="step">Step</button>
  <button id="play">Play</button>
  <button id="random">Randomize</button>
  <button id="clear">Clear</button>
</div>

<canvas id="life"></canvas>

<script>
(function() {
    const GRID_W = 50; // >=40
    const GRID_H = 50; // >=40
    const CELL_SIZE = 12; 

    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d', { alpha: false });

    // Set internal resolution to match logical grid * cellSize for crisp rendering
    canvas.width = GRID_W * CELL_SIZE; 
    canvas.height = GRID_H * CELL_SIZE;

    let grid = createGrid(GRID_W, GRID_H);

    function createGrid(w, h) {
        const arr = new Array(h);
        for(let y=0; y<h; y++) {
            arr[y] = new Uint8Array(w); 
        }
        return arr;
    }

    window.life = {};
    Object.defineProperty(window.life, 'w', { get: () => GRID_W });
    Object.defineProperty(window.life, 'h', { get: () => GRID_H });

    // API: Get cell value (0 or 1) -> Returns 0 for out-of-bounds
    window.life.get = function(x, y) {
        if (!Number.isInteger(x) || !Number.isInteger(y)) return 0;
        x = Math.floor(x); 
        y = Math.floor(y);
        if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return 0;
        return grid[y][x];
    };

    // API: Set cell value (truthy becomes 1, falsy 0) -> Silently ignores OOB
    window.life.set = function(x, y, v) {
        if (!Number.isInteger(x) || !Number.isInteger(y)) return;
        x = Math.floor(x); 
        y = Math.floor(y);
        if (x >= 0 && x < GRID_W && y >= 0 && y < GRID_H) {
            grid[y][x] = v ? 1 : 0;
        }
    };

    // API: Step one generation and redraw
    window.life.step = function() { stepGrid(); drawGrid(); };

    // API: Clear all cells and redraw
    window.life.clear = function() { clearGrid(); drawGrid(); };

    function stepGrid() {
        const next = createGrid(GRID_W, GRID_H);

        for(let y=0; y<GRID_H; y++) {
            for(let x=0; x<GRID_W; x++) {
                let neighbors = 0;

                // Check all 8 neighbors. Edges count as dead (outside bounds = 0).
                for(let dy=-1; dy<=1; dy++) {
                    for(let dx=-1; dx<=1; dx++) {
                        if(dx===0 && dy===0) continue;

                        const nx = x + dx;
                        const ny = y + dy;

                        if(nx >= 0 && nx < GRID_W && ny >= 0 && ny < GRID_H) {
                            neighbors += grid[ny][nx];
                        }
                    }
                }

                const current = grid[y][x];

                // B3/S23 Rules
                if (current === 1) {
                    next[y][x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
                } else {
                    next[y][x] = (neighbors === 3) ? 1 : 0;
                }
            }
        }
        grid = next; 
    }

    function clearGrid() {
        for(let y=0; y<GRID_H; y++) {
            grid[y].fill(0);
        }
    }

    function drawGrid() {
        ctx.fillStyle = '#1a1a1a'; // Background color (Dark theme)
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Live Cells Color - Neon Cyan for Playfulness on Dark Theme
        ctx.fillStyle = '#4fffa6'; 

        for(let y=0; y<GRID_H; y++) {
            for(let x=0; x<GRID_W; x++) {
                if(grid[y][x]) {
                    // Draw rect with slight gap to visualize grid lines (if desired) or solid blocks.
                    ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE - 1, CELL_SIZE - 1);
                }
            }
        }
    }

    let isMouseDown = false;

    function getCellPos(evt) {
        const rect = canvas.getBoundingClientRect();
        // Handle pixel density scaling if needed, here we keep it simple: mapping visual coords to internal resolution.
        // Since CSS size matches Internal Size (600x600), scaleX/scaleY are effectively 1 usually, 
        // but calculating ensures correctness even with borders or different rendering sizes.
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;

        return {
            x: Math.floor((evt.clientX - rect.left) * scaleX / CELL_SIZE),
            y: Math.floor((evt.clientY - rect.top) * scaleY / CELL_SIZE)
        };
    }

    function paintCell(evt, cellX, cellY) {
        // Toggle logic as requested: click/drag toggles state.
        if(window.life.get(cellX, cellY)) {
             window.life.set(cellX, cellY, 0);
        } else {
             window.life.set(cellX, cellY, 1);
        }
    }

    canvas.addEventListener('mousedown', (e) => {
        isMouseDown = true;
        const pos = getCellPos(e);
        paintCell(e, pos.x, pos.y);
    });

    canvas.addEventListener('mousemove', (e) => {
        if (!isMouseDown) return;
        e.preventDefault(); // Prevent scroll/selection
        const pos = getCellPos(e);
        paintCell(e, pos.x, pos.y);
    });

    window.addEventListener('mouseup', () => isMouseDown = false);

    document.getElementById('step').addEventListener('click', () => { stepGrid(); drawGrid(); });

    let autoRunInterval = null;
    const playBtn = document.getElementById('play');

    function toggleAutoRun() {
        if (autoRunInterval) {
            clearInterval(autoRunInterval);
            autoRunInterval = null;
            playBtn.textContent = 'Play'; 
            playBtn.classList.remove('active-state'); 
        } else {
            // Start Interval
            autoRunInterval = setInterval(() => {
                stepGrid(); drawGrid();
            }, 100); // Speed (ms per gen)

            playBtn.textContent = 'Stop'; 
            playBtn.classList.add('active-state');
        }
    }

    playBtn.addEventListener('click', toggleAutoRun);

    document.getElementById('random').addEventListener('click', () => {
        for(let y=0; y<GRID_H; y++) {
            for(let x=0; x<GRID_W; x++) {
                // ~25% probability of being alive
                grid[y][x] = Math.random() > 0.75 ? 1 : 0;
            }
        }
        drawGrid();
    });

    document.getElementById('clear').addEventListener('click', () => { clearGrid(); drawGrid(); });

    // Initial Draw
    drawGrid();

})();
</script>

</body>
</html>
